import { readFileSync } from "node:fs";
import { formatHex, hexKey, parseNumber } from "../hex.js";
import { uri } from "../interrupts/render.js";
import { decodeFields, fieldLayout, GROUP_NOTES, INDEXED_FILES, SINGLE_PORTS, type IndexedFile, type RegDoc } from "./registers.js";

interface PortTables {
  singles: Array<{ port: number; text: string }>;
  ranges: Array<{ start: number; end: number; text: string }>;
}
let portTables: PortTables | undefined;
function getPortTables(): PortTables {
  if (!portTables) {
    // data/memory-tables.json is generated by scripts/build_data.py, so its shape is trusted.
    const tables: { ports: PortTables } = JSON.parse(readFileSync(new URL("../../data/memory-tables.json", import.meta.url), "utf8"));
    portTables = tables.ports;
  }
  return portTables;
}

export interface PortOutput {
  port: string;
  role: string;
  access: "read" | "write" | "read/write" | "unknown";
  documentation: string;
}
export type PortResult = { ok: true; output: PortOutput } | { ok: false; error: string };

/** Ports that decode to the CRTC pair or the SN76496 (Tandy manual). */
const MIRRORS = new Map<number, number>([
  [0x3b0, 0x3b4], [0x3b2, 0x3b4], [0x3b6, 0x3b4], [0x3b1, 0x3b5], [0x3b3, 0x3b5], [0x3b7, 0x3b5],
  [0x3d0, 0x3d4], [0x3d2, 0x3d4], [0x3d6, 0x3d4], [0x3d1, 0x3d5], [0x3d3, 0x3d5], [0x3d7, 0x3d5],
  ...[1, 2, 3, 4, 5, 6, 7].map((n) => [0xc0 + n, 0xc0] as [number, number]),
]);

const hex = (n: number, w = 2) => formatHex(n, w);

function describeRegister(file: IndexedFile, index: number, value: number | undefined): { name: string; text: string; reg?: RegDoc } {
  const reg = file.registers[index];
  if (!reg) {
    return {
      name: `index ${hex(index)}`,
      text: `Index ${hex(index)} is not a documented ${file.title.split(" (")[0]} register (it may be an SVGA/chipset extension, or the index byte includes flag bits).`,
    };
  }
  const lines = [`**${reg.name}** (index ${hex(index)}, ${reg.access})`, reg.summary];
  if (value !== undefined) {
    const dec = decodeFields(reg.fields, value);
    if (dec.length) lines.push(`Value ${hex(value)} (${value}) decodes as:\n${dec.map((d) => `- ${d}`).join("\n")}`);
    else lines.push(`Value written: ${hex(value)} (${value}).`);
  }
  return { name: reg.name, text: lines.join("\n"), reg };
}

function indexedList(file: IndexedFile): string {
  return Object.entries(file.registers)
    .filter(([i]) => file.id !== "vga-attribute" || Number(i) >= 0x10 || Number(i) === 0)
    .map(([i, r]) => `- ${hex(Number(i))}: ${r.name}`)
    .join("\n") + (file.id === "vga-attribute" ? "\n- 01-0F: Palette Registers 1-F" : "");
}

const PSG_REGISTERS = ["tone 0 frequency divider", "tone 0 attenuation", "tone 1 frequency divider", "tone 1 attenuation", "tone 2 frequency divider", "tone 2 attenuation", "noise control", "noise attenuation"];

/** Decode one byte written to the SN76496: latch byte (bit 7 set) or data/continuation byte. */
function decodeSn76496(value: number): string[] {
  if (value > 0xff) return ["SN76496 takes single bytes; a 16-bit OUT sends only AL on most hardware."];
  if (!(value & 0x80)) {
    return [`continuation byte: bits 9..4 of the divider for the register selected by the last latch byte = ${hex(value & 0x3f)} (divider high part; divider = (${value & 0x3f} << 4) | latch low nibble)`];
  }
  const reg = (value >> 4) & 7;
  const data = value & 0xf;
  const lines = [`latch byte: register ${reg} (${PSG_REGISTERS[reg]}), data nibble ${hex(data)}`];
  if (reg % 2 === 1) lines.push(`attenuation ${data}: ${data === 0 ? "full volume" : data === 15 ? "OFF (silent)" : `${data * 2} dB quieter`}`);
  else if (reg === 6) lines.push(`noise: ${data & 4 ? "white" : "periodic"} noise, rate ${data & 3}${(data & 3) === 3 ? " (follows tone 2's divider)" : ""}`);
  else lines.push(`divider low 4 bits = ${data}; follow with a continuation byte (bit 7 clear) for bits 9..4. Frequency = 111860.78 / divider Hz`);
  return lines;
}

export function lookupPort(input: { port: unknown; index?: unknown; value?: unknown }): PortResult {
  const portN = parseNumber(input.port, 0xffff, "port");
  if (!portN.ok) return { ok: false, error: portN.error };
  const idx = input.index === undefined ? undefined : parseNumber(input.index, 0xff, "index");
  if (idx && !idx.ok) return { ok: false, error: idx.error };
  const val = input.value === undefined ? undefined : parseNumber(input.value, 0xffff, "value");
  if (val && !val.ok) return { ok: false, error: val.error };
  const given = portN.value;
  const index = idx?.ok ? idx.value : undefined;
  const value = val?.ok ? val.value : undefined;

  const port = MIRRORS.get(given) ?? given;
  const mirrorNote = port !== given ? `Port ${hex(given, 3)} decodes to ${hex(port, 3)} on this hardware (Tandy manual). ` : "";
  const label = (name: string) => `${hex(given, 3)} (${name})`;
  const notes = (group: string) => (GROUP_NOTES[group] ? `\nMore: ${uri.port(group)}` : "");

  // ---- indexed register families
  for (const file of INDEXED_FILES) {
    const isAddress = file.addressPorts.includes(port);
    const isData = file.dataPorts.includes(port);
    if (!isAddress && !isData) continue;
    const dataPort = file.dataPorts.find((p) => p === port + 1) ?? file.dataPorts[0]!;
    const flipFlop = file.id === "vga-attribute";

    if (flipFlop) {
      // 3C0 alternates address/data; 3C1 is the read side.
      if (port === 0x3c1) {
        const r = index !== undefined ? describeRegister(file, index, value) : undefined;
        return ok(label("Attribute Controller data read"), "Attribute Controller (read side)", "read", [mirrorNote + file.summary, r?.text ?? `Reads the register last selected through 3C0h. Registers:\n${indexedList(file)}`], notes(file.id));
      }
      if (index !== undefined) {
        const r = describeRegister(file, index, value);
        return ok(label(`Attribute ${r.name}`), `Attribute Controller: ${r.name}`, r.reg?.access ?? "write", [`Treated as the DATA write for register ${hex(index)} (the address byte was written first).`, r.text, file.summary], notes(file.id));
      }
      if (value !== undefined) {
        const reg = value & 0x1f;
        const r = describeRegister(file, reg, undefined);
        return ok(label("Attribute address byte"), "Attribute Controller (address phase)", "write", [`If the flip-flop is in the ADDRESS state (it is after reading 3DAh), ${hex(value)} selects register ${hex(reg)}: ${r.name}. Bit 5 (${value & 0x20 ? "set" : "clear"}) ${value & 0x20 ? "keeps the screen on (palette fed from video memory)" : "blanks the screen so the palette can be loaded"}. If instead it is in the DATA state, the byte is the value for the previously selected register; pass \`index\` to describe that case.`, r.text, file.summary], notes(file.id));
      }
      return ok(label("Attribute Controller"), file.title, "read/write", [file.summary, `Registers:\n${indexedList(file)}`], notes(file.id));
    }

    if (isAddress) {
      // value <= FFh: index byte. value > FFh: 16-bit OUT DX,AX => AL = index, AH = data.
      if (value === undefined) return ok(label(`${file.id} index`), `${file.title.split(" (")[0]}: register index`, "write", [mirrorNote + file.summary, `Write a register index here, then the data to ${hex(dataPort, 3)}. Registers:\n${indexedList(file)}`], notes(file.id));
      const sel = value & 0xff;
      const first = describeRegister(file, sel, undefined);
      if (value <= 0xff) return ok(label(`${file.id} index`), `${file.title.split(" (")[0]}: selects ${first.name}`, "write", [`Selects register ${hex(sel)}: ${first.name}. The next access to ${hex(dataPort, 3)} reads/writes it.`, first.text], notes(file.id));
      const data = value >> 8;
      const both = describeRegister(file, sel, data);
      return ok(label(`${file.id} index+data (16-bit OUT)`), `${file.title.split(" (")[0]}: sets ${both.name}`, "write", [`A 16-bit \`OUT DX,AX\` to ${hex(port, 3)} writes AL=${hex(sel)} to the index port and AH=${hex(data)} to ${hex(dataPort, 3)} in one instruction.`, both.text], notes(file.id));
    }

    // data port
    if (index === undefined) {
      return ok(label(`${file.id} data`), `${file.title.split(" (")[0]}: data`, "read/write", [mirrorNote + `This is the data port; which register it hits depends on the index last written to ${hex(file.addressPorts[file.dataPorts.indexOf(port)] ?? file.addressPorts[0]!, 3)}. Provide \`index\` to identify it.`, `Registers:\n${indexedList(file)}`], notes(file.id));
    }
    const r = describeRegister(file, index, value);
    return ok(label(`${file.id}: ${r.name}`), `${file.title.split(" (")[0]}: ${r.name}`, r.reg?.access ?? "unknown", [r.text, file.summary], notes(file.id));
  }

  // ---- single documented ports
  const single = SINGLE_PORTS[port];
  if (single) {
    const docs = [mirrorNote + single.summary];
    const dec = value === undefined ? [] : port === 0xc0 ? decodeSn76496(value) : decodeFields(single.fields, value);
    if (value !== undefined && dec.length) docs.push(`Value ${hex(value)} (${value}) decodes as:\n${dec.map((d) => `- ${d}`).join("\n")}`);
    else if (single.fields?.length) docs.push("Bit layout: " + fieldLayout(single.fields).join("; "));
    return ok(label(single.name), single.name, single.access, docs, notes(single.group));
  }

  // ---- bundled table fallback: exact port, then range
  const hp = getPortTables();
  const exact = hp.singles.filter((s) => s.port === port);
  const range = hp.ranges.filter((r) => port >= r.start && port <= r.end).sort((a, b) => a.end - a.start - (b.end - b.start))[0];
  if (exact.length || range) {
    const lines = exact.map((e) => `Port ${hex(port, 3)}: ${e.text}`);
    if (range) lines.push(`Range ${hex(range.start, 3)}-${hex(range.end, 3)}: ${range.text}`);
    lines.push("Source: common I/O port addresses (PC/XT unless marked; may differ on AT/PS/2). Full table: " + uri.port("table"));
    const role = range && exact[0] ? `${range.text}: ${exact[0].text}` : (exact[0]?.text ?? `${range!.text} (range ${hex(range!.start, 3)}-${hex(range!.end, 3)})`);
    return ok(label(role), role, "unknown", lines, "");
  }
  return {
    ok: true,
    output: {
      port: hex(port, 3),
      role: "Not in the bundled port tables",
      access: "unknown",
      documentation:
        `No bundled reference covers port ${hex(port, 3)}. It is probably an add-in card (sound, network, SCSI, ...) or a game-specific/copy-protection port. ` +
        `Check what the surrounding code does: which device it talks to usually shows in the sequence of ports used next to it. Full table of known ports: ${uri.port("table")}`,
    },
  };

  function ok(portLabel: string, role: string, access: PortOutput["access"], text: string[], more: string): PortResult {
    return { ok: true, output: { port: portLabel, role, access, documentation: text.filter(Boolean).join("\n\n") + more } };
  }
}

export function renderPortDoc(id: string): string | undefined {
  if (id === "table") {
    const hp = getPortTables();
    const ranges = hp.ranges.map((r) => `${hexKey(r.start, 3)}-${hexKey(r.end, 3)}\t${r.text}`);
    const singles = hp.singles.map((s) => `${hexKey(s.port, 3)}\t${s.text}`);
    return `# Common PC I/O port addresses\n\nPC/XT unless marked; AT/PS/2 differ for some.\n\n## Ranges\n\n\`\`\`\n${ranges.join("\n")}\n\`\`\`\n\n## Individual ports\n\n\`\`\`\n${singles.join("\n")}\n\`\`\``;
  }
  const file = INDEXED_FILES.find((f) => f.id === id);
  if (file) {
    const rows = Object.entries(file.registers).map(([i, r]) => {
      const fields = r.fields?.length ? "\n" + fieldLayout(r.fields).map((l) => `    - ${l}`).join("\n") : "";
      return `- **${hex(Number(i))} ${r.name}** (${r.access}): ${r.summary}${fields}`;
    });
    return `# ${file.title}\n\n${file.summary}\n\n${rows.join("\n")}`;
  }
  return GROUP_NOTES[id];
}

export const PORT_DOC_IDS: readonly string[] = [...INDEXED_FILES.map((f) => f.id), ...Object.keys(GROUP_NOTES).filter((k) => !INDEXED_FILES.some((f) => f.id === k)), "table"];
